WITH RECURSIVE all_comment_tree AS ( SELECT c.comment_id, c.parent_comment_id, c.deleted_yn, c.comment_id AS root_comment_id FROM tb_common_comment c WHERE c.tenant_id = #{tenantId} AND c.owner_type = #{ownerType} AND c.owner_id = #{ownerId} AND c.parent_comment_id IS NULL UNION ALL SELECT child.comment_id, child.parent_comment_id, child.deleted_yn, tree.root_comment_id FROM tb_common_comment child JOIN all_comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = #{ownerType} AND child.owner_id = #{ownerId} AND child.comment_id <> ALL(ARRAY[tree.comment_id]) ), root_page AS ( SELECT root_comment_id AS comment_id, ROW_NUMBER() OVER (ORDER BY root_comment_id DESC) AS root_order FROM all_comment_tree GROUP BY root_comment_id HAVING BOOL_OR(deleted_yn = 'N')
AND root_comment_id < #{beforeCommentId}
ORDER BY root_comment_id DESC LIMIT #{limit} ), comment_tree AS ( SELECT c.comment_id, c.tenant_id, c.owner_type, c.owner_id, c.parent_comment_id, c.content, c.writer_id, c.writer_name, c.deleted_yn, c.created_at, c.updated_at, rp.root_order, ARRAY[c.comment_id] AS comment_path FROM tb_common_comment c JOIN root_page rp ON rp.comment_id = c.comment_id UNION ALL SELECT child.comment_id, child.tenant_id, child.owner_type, child.owner_id, child.parent_comment_id, child.content, child.writer_id, child.writer_name, child.deleted_yn, child.created_at, child.updated_at, tree.root_order, tree.comment_path || child.comment_id FROM tb_common_comment child JOIN comment_tree tree ON tree.comment_id = child.parent_comment_id WHERE child.tenant_id = #{tenantId} AND child.owner_type = #{ownerType} AND child.owner_id = #{ownerId} AND NOT child.comment_id = ANY(tree.comment_path) ) SELECT comment_id, tenant_id, owner_type, owner_id, parent_comment_id, content, writer_id, writer_name, deleted_yn, created_at, updated_at FROM comment_tree ORDER BY root_order, comment_path

SELECT COUNT(*)
FROM tb_common_comment
WHERE tenant_id = #{tenantId}
  AND owner_type = #{ownerType}
  AND owner_id = #{ownerId}
  AND deleted_yn = 'N'

