UPDATE tb_common_comment
SET content = #{content},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND comment_id = #{commentId}
            AND writer_id = #{actorId}
            AND deleted_yn = 'N'

UPDATE tb_common_comment
SET deleted_yn = 'Y',
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND comment_id = #{commentId}
            AND writer_id = #{actorId}
            AND deleted_yn = 'N'
